package main

import (
	"encoding/json"
	"fmt"
	"io"

	"github.com/agentydragon/ducktape/agentplane/app/go/policyaccess"
)

// exportOpenAPI registers the application's typed routes and writes the OpenAPI document
// generated by Huma. The zero-value services are registration placeholders: Huma reads the
// operation declarations without invoking handlers.
func exportOpenAPI(writer io.Writer) error {
	server := NewHTTPServer(nil)
	defer server.Close()
	config := Config{}
	if err := RegisterCoreRoutes(server, config); err != nil {
		return fmt.Errorf("register core routes: %w", err)
	}
	RegisterPolicyRoutes(server, config, nil, (*policyaccess.Access)(nil))
	if err := RegisterThreadReadRoutes(server, nil, nil, nil, nil); err != nil {
		return fmt.Errorf("register Thread routes: %w", err)
	}
	RegisterOperatorRoutes(server, nil, nil, nil, nil, "")
	RegisterStatusRoutes(server, nil)

	encoded, err := json.MarshalIndent(server.api.OpenAPI(), "", "  ")
	if err != nil {
		return fmt.Errorf("encode Huma OpenAPI document: %w", err)
	}
	_, err = writer.Write(append(encoded, '\n'))
	return err
}
